def check_course_blocks(course, expected_blocks, unexpected_blocks):
    """
    Check that the course has the expected blocks and does not have the unexpected blocks
    """
    for block in expected_blocks:
        if block not in course:
            return False
    for block in unexpected_blocks:
        if block in course:
            return False
    return True

def _process_raw_lines(raw_lines):
    buffer = []
    for line in raw_lines:
        line = line.strip()
        if not line or line.startswith('!'):
            continue
        comment_index = line.find('!')
        if comment_index != -1:
            line = line[:comment_index]
        line = line.rstrip()
        if line.endswith('&'):
            buffer.append(line.rstrip('&').strip())
        else:
            buffer.append(line)
            yield ' '.join(buffer)
            buffer = []
    if buffer:
        yield ' '.join(buffer)

